function galleryCard(g, big) {
  const h = big ? 170 : 92;
  return `<div style="display:flex;align-items:center;gap:10px;justify-content:${big ? 'center' : 'flex-start'}"><img src="${g[3]}" alt="" style="height:${h}px;max-width:${big ? 160 : 86}px;object-fit:contain;border-radius:6px;background:#efe8d8;transform:rotate(-2deg);box-shadow:0 2px 8px #0008"><span style="color:#ffd36a;font-size:${big ? 22 : 16}px">&rarr;</span><img src="${g[4]}" alt="" style="height:${h}px;object-fit:contain"><div style="text-align:left;line-height:1.3;min-width:${big ? 170 : 0}px"><b>${g[1]}</b><br><small style="color:#aab">${g[2]}</small></div></div>`;
}
function openGallery() {
  openDlg('Codex', 'From the notebooks'); $('dlgLine').textContent = "Phil & Caleb's high-school drawings, next to the characters they became.";
  const rows = document.createElement('div'); rows.className = 'rows'; rows.id = 'shopRows'; rows.style.cssText = 'max-height:56vh;overflow-y:auto';
  const grid = document.createElement('div'); grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px;padding:4px 2px';
  grid.innerHTML = GALLERY.map(g => `<div style="padding:8px;border:1px solid var(--edge);background:#0008">${galleryCard(g)}</div>`).join(''); rows.appendChild(grid);
  $('dlgActs').before(rows); acts([['Back to credits', () => openCodex('credits'), true], ['Close', closeDlg]]);
}
{ const _o = openCodex; openCodex = function (tab) { const r = _o.apply(this, arguments); try { const rows = (tab === 'credits') && $('shopRows'); if (rows) { const d = document.createElement('div'); d.className = 'rowi nodot'; d.innerHTML = '<b>From the notebooks</b><span></span>'; const b = document.createElement('button'); b.className = 'pbtn'; b.textContent = 'See the drawings'; b.addEventListener('click', e => { e.stopPropagation(); SFX.ui(); openGallery(); }); d.appendChild(b); rows.prepend(d); pageRows(); } } catch (e) { console.warn('gallery', e); } return r; }; }
